const AUTH_USER_KEY = "user";
const SESSION_ID_KEY = "sessionId";
const TAB_INSTANCE_ID_KEY = "tabInstanceId";

// Generate a unique ID for this browser tab instance (in memory)
let TAB_INSTANCE_ID = null;

function generateTabInstanceId() {
  return `tab_${Date.now()}_${Math.random().toString(36).substr(2, 12)}`;
}

// Get or create the tab instance ID (in memory, not persisted)
function getTabInstanceId() {
  if (!TAB_INSTANCE_ID) {
    TAB_INSTANCE_ID = generateTabInstanceId();
  }
  return TAB_INSTANCE_ID;
}

// Generate a unique session ID for this tab
function generateSessionId() {
  return `${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
}

// Initialize or get the session ID for this tab
// Returns { sessionId, isNewSession: boolean, isDuplicatedTab: boolean }
export function getOrCreateSessionId() {
  const currentTabId = getTabInstanceId();
  let storedTabId = sessionStorage.getItem(TAB_INSTANCE_ID_KEY);
  let sessionId = sessionStorage.getItem(SESSION_ID_KEY);
  let isNewSession = false;
  let isDuplicatedTab = false;

  // Check if this is a duplicated tab (sessionStorage was copied but we have a new tab instance)
  if (storedTabId && storedTabId !== currentTabId) {
    isDuplicatedTab = true;
    // Clear the session for this tab
    clearAuthUser();
    return { sessionId: null, isNewSession: false, isDuplicatedTab: true };
  }

  // First time this tab is running
  if (!sessionId) {
    sessionId = generateSessionId();
    sessionStorage.setItem(SESSION_ID_KEY, sessionId);
    sessionStorage.setItem(TAB_INSTANCE_ID_KEY, currentTabId);
    isNewSession = true;
  } else {
    // Session exists and tab ID matches - this is the same tab
    sessionStorage.setItem(TAB_INSTANCE_ID_KEY, currentTabId);
  }

  return { sessionId, isNewSession, isDuplicatedTab };
}

// Verify the session ID is still valid for this tab
export function isSessionValid() {
  return sessionStorage.getItem(SESSION_ID_KEY) !== null;
}

export function readAuthUser() {
  try {
    // Check if session is still valid (tab still has its session ID)
    if (!isSessionValid()) {
      return null;
    }
    const stored = sessionStorage.getItem(AUTH_USER_KEY);
    return stored ? JSON.parse(stored) : null;
  } catch {
    return null;
  }
}

export function writeAuthUser(user) {
  // Ensure session ID exists
  getOrCreateSessionId();
  sessionStorage.setItem(AUTH_USER_KEY, JSON.stringify(user));
  localStorage.removeItem(AUTH_USER_KEY);
}

export function clearAuthUser() {
  sessionStorage.removeItem(AUTH_USER_KEY);
  sessionStorage.removeItem(SESSION_ID_KEY);
  localStorage.removeItem(AUTH_USER_KEY);
}
